package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.io.StringWriter;
import java.lang.reflect.Field;
import java.math.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.Arrays;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.apache.commons.compress.utils.CharsetNames;
import org.apache.commons.compress.utils.CountingOutputStream;
import org.apache.commons.compress.utils.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarArchiveOutputStream_TarArchiveOutputStream_TriageGen0Test {

    @Test
    public void testConstructorSuccess() throws Exception {
        OutputStream os = new ByteArrayOutputStream();
        int blockSize = 512;
        int recordSize = 128;
        String encoding = "UTF-8";

        TarArchiveOutputStream tarOut = new TarArchiveOutputStream(os, blockSize, recordSize, encoding);

        // Use reflection to verify internal state for coverage/validation
        assertEquals(recordSize, getInternalField(tarOut, "recordSize"));
        assertEquals(blockSize / recordSize, getInternalField(tarOut, "recordsPerBlock"));
        assertEquals(0, getInternalField(tarOut, "assemLen"));

        byte[] assemBuf = (byte[]) getInternalField(tarOut, "assemBuf");
        assertEquals(recordSize, assemBuf.length);

        byte[] recordBuf = (byte[]) getInternalField(tarOut, "recordBuf");
        assertEquals(recordSize, recordBuf.length);

        tarOut.close();
    }

    @Test
    public void testConstructorWithNullEncoding() throws Exception {
        // Testing how ZipEncodingHelper handles null based on standard Commons Compress behavior
        OutputStream os = new ByteArrayOutputStream();
        TarArchiveOutputStream tarOut = new TarArchiveOutputStream(os, 512, 512, null);

        // If ZipEncodingHelper returns a default for null, verify it doesn't crash
        // This ensures the line 'this.zipEncoding = ZipEncodingHelper.getZipEncoding(encoding);' is covered
        tarOut.close();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructorWithInvalidRecordSize() throws Exception {
        // If recordSize is 0, it might cause ArithmeticException in recordsPerBlock calculation
        // or be invalid for array allocation.
        OutputStream os = new ByteArrayOutputStream();
        new TarArchiveOutputStream(os, 512, 0, "UTF-8");
    }

    @Test(expected = NegativeArraySizeException.class)
    public void testConstructorWithNegativeRecordSize() throws Exception {
        OutputStream os = new ByteArrayOutputStream();
        new TarArchiveOutputStream(os, 512, -1, "UTF-8");
    }

    /**
     * Helper method to access private fields for verification
     */
    private Object getInternalField(Object obj, String fieldName) throws Exception {
        Field field = obj.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(obj);
    }
}
